import{_ as r,o as e,c as t,O as o}from"./chunks/framework.db831a78.js";const c=JSON.parse('{"title":"Java 基础","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/01-Java基础.md","filePath":"interview/后端/Java/01-Java基础.md","lastUpdated":1788851914000}'),n={name:"interview/后端/Java/01-Java基础.md"};function s(i,a,l,h,p,d){return e(),t("div",null,a[0]||(a[0]=[o('<h1 id="java-基础" tabindex="-1">Java 基础 <a class="header-anchor" href="#java-基础" aria-label="Permalink to &quot;Java 基础&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-与-equals、hashcode-契约-★★★" tabindex="-1">1. == 与 equals、hashCode 契约 ★★★ <a class="header-anchor" href="#_1-与-equals、hashcode-契约-★★★" aria-label="Permalink to &quot;1. == 与 equals、hashCode 契约 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>==</code> 问的是「是不是同一个东西」——基本类型比值，对象比地址。<code>equals</code> 默认也问地址，但 String、Integer 这些类把它改成了「内容一样就算相等」。<code>hashCode</code> 是给 HashMap 定位桶用的门牌号。契约一句话：两个对象 equals 相等，hashCode 必须相等。</p><p><strong>我的项目关联</strong> 设备会话、订单这类对象我们放在 Map / Set 里做去重和缓存，比如网关里按设备编号聚合的会话表。自定义对象只要会进集合，equals 和 hashCode 就成对重写，否则 Set 里能塞进重复对象、Map 里 get 不到。这条属于「通用坑」，我们项目没实际踩过，但一直是个硬规范。</p><p><strong>面试答题话术</strong> 「<code>==</code> 比的是地址或值，<code>equals</code> 默认也是比地址，只有 String 这类重写过的才是比值。核心契约是重写 equals 必须重写 hashCode，不然两个 equals 相等的对象 hashCode 不同，会落到不同桶，Set 能重复、Map get 不到。我项目里设备和订单对象会进 Map 做缓存，所以我的习惯是只要这个对象会进集合，这俩方法就成对重写。」</p><hr><h2 id="_2-string-不可变-常量池-stringbuilder-★★★" tabindex="-1">2. String 不可变 / 常量池 / StringBuilder ★★★ <a class="header-anchor" href="#_2-string-不可变-常量池-stringbuilder-★★★" aria-label="Permalink to &quot;2. String 不可变 / 常量池 / StringBuilder ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> String 创建后内容改不了，每次「修改」都是 new 一个新对象。好处是能安全共享、能当 HashMap 的 key（hash 不会变）。要频繁拼字符串就用 StringBuilder（快、线程不安全），多线程共享一个再考虑 StringBuffer。字符串常量池就是 String 的公共仓库，字面量直接复用。</p><p><strong>我的项目关联</strong> 网关拼装下发给充电桩的控制报文、拼装查询日志、互联互通拼签名原文，用的都是 StringBuilder。设备号、订单号这种高复用字符串天然吃到常量池的好处。这块属于常规用法，没有踩过坑。</p><p><strong>面试答题话术</strong> 「String 不可变，所以能安全共享、能当 Map 的 key；代价是每次拼接都产生新对象，所以频繁拼接我用 StringBuilder。经典题 <code>new String(&quot;a&quot;)</code> 会产生两个对象，一个在常量池一个在堆，日常代码不会这么写。JDK9 之后 String 底层从 char 数组换成了 byte 数组，省一半空间，这个细节我答得出来但其实不影响用。」</p><hr><h2 id="_3-arraylist-linkedlist-扩容-★★★" tabindex="-1">3. ArrayList / LinkedList / 扩容 ★★★ <a class="header-anchor" href="#_3-arraylist-linkedlist-扩容-★★★" aria-label="Permalink to &quot;3. ArrayList / LinkedList / 扩容 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> ArrayList 就是一个能自动扩容的数组：按下标取元素快，中间插入删除慢（要挪后面的元素），满了自动扩到 1.5 倍。LinkedList 是双向链表，头尾操作快，但按下标找要一个个遍历，而且内存不连续、吃不到 CPU 缓存，所以实际用得非常少。</p><p><strong>我的项目关联</strong> 设备列表下发、订单批量处理、导出的数据集合都用 ArrayList，能预判大小的场景（比如按批次查出来的订单）我会给个初始容量，少扩几次容。LinkedList 项目里基本没出现过。 <strong>通用坑</strong>：for-each 里直接调 <code>list.remove()</code> 会抛 ConcurrentModificationException，得用 <code>iterator.remove()</code> 或者 <code>removeIf</code>。</p><p><strong>面试答题话术</strong> 「ArrayList 是数组，随机访问 O(1)，中间增删 O(n)，扩容 1.5 倍；LinkedList 是链表，头尾快但按下标找要遍历，而且内存不连续，实际性能经常还不如 ArrayList，所以项目里我基本只用 ArrayList。能预估大小的集合我会带初始容量，避免反复扩容。这个坑我是踩过的——遍历中直接 remove 会抛 ConcurrentModificationException，后来统一用 removeIf。」</p><hr><h2 id="_4-hashmap-底层原理-★★★" tabindex="-1">4. HashMap 底层原理 ★★★ <a class="header-anchor" href="#_4-hashmap-底层原理-★★★" aria-label="Permalink to &quot;4. HashMap 底层原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> HashMap = 「数组桶 + 链表/红黑树」。先用 key 的 hash 找到桶：桶是空的直接放，冲突了就挂成链表，链太长（8 个且数组 ≥ 64）转红黑树，把最坏查询从 O(n) 压到 O(logn)。容量固定取 2 的幂，这样能用位运算代替取模，而且扩容时只看多出来的那一位，不用重算 hash。负载因子 0.75 是空间和时间的折中。</p><p><strong>我的项目关联</strong> 网关里用 Map 做本地缓存和分组：设备号 → 会话状态、场站 → 枪状态、协议类型 → 命令处理器表。<strong>这条必须强调</strong>：网关是多线程环境（Netty Worker 线程 + Kafka 消费线程都在跑），所以生产代码里并发场景一律用 ConcurrentHashMap，不用 HashMap。1.7 头插法并发扩容会成环把 CPU 打满，属于历史坑，我是查资料时确认的，没在线上的 1.8 环境遇到过。</p><p><strong>面试答题话术</strong> 「HashMap 是数组加链表加红黑树。三个点：一是容量取 2 的幂，为了用位运算代替取模，扩容时只看多出来那一位是 0 还是 1，不用重算 hash；二是扰动函数把高位异或进低位，降低碰撞；三是 8 树化、6 退化，中间留缓冲防止抖动。项目里我的结论是并发场景绝对不用 HashMap——我们的协议网关是多线程的，本地缓存全用 ConcurrentHashMap。」</p><hr><h2 id="_5-concurrenthashmap-★★★" tabindex="-1">5. ConcurrentHashMap ★★★ <a class="header-anchor" href="#_5-concurrenthashmap-★★★" aria-label="Permalink to &quot;5. ConcurrentHashMap ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 1.7 是分段锁：整个表切成若干 Segment，每个 Segment 一把锁，锁的是「段」。1.8 改成「桶级锁」：写只对某个桶的头节点加 synchronized，空桶用 CAS 直接写，读完全不加锁；扩容时多个线程能一起帮忙搬。锁粒度从段细化到桶，并发度自然更高。</p><p><strong>我的项目关联</strong> 网关的设备会话表、协议命令表（<code>协议类型 + 命令字 → 处理器</code>）都用 ConcurrentHashMap，因为会被 Netty 线程和业务线程同时读写。<strong>线上</strong>：命令表在应用启动时由主线程注册、运行时被 IO 线程读，用 ConcurrentHashMap 就是保证注册过程可见、读取安全，这块没出过问题，但选型上是我明确考虑过的。</p><p><strong>面试答题话术</strong> 「1.7 是 Segment 分段锁，1.8 改成桶级：写的时候只锁桶的头节点，空桶用 CAS，读完全无锁，靠 volatile 保证可见性，扩容还能多线程一起搬。所以 1.8 并发度比 1.7 高不少。项目里网关的命令表和设备会话表都用它，因为是多线程读写。另外它不允许 null 的 key 和 value——因为并发下 get 返回 null 没法区分是「没有」还是「存了个 null」，这个设计原因我会顺便讲。」</p><hr><h2 id="_6-集合框架选型-★★★" tabindex="-1">6. 集合框架选型 ★★★ <a class="header-anchor" href="#_6-集合框架选型-★★★" aria-label="Permalink to &quot;6. 集合框架选型 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 按需求挑：List 要按序可重复（读多 ArrayList）；Set 要去重（HashSet 最快，要顺序用 LinkedHashSet，要排序用 TreeSet）；Map 要键值（HashMap 最快，要顺序用 LinkedHashMap，要排序用 TreeMap，要并发用 ConcurrentHashMap）。</p><p><strong>我的项目关联</strong> 协议命令表用 Map、设备在线列表用 Set 去重、批量下发用 List。数据同步、批量写库这种读多写少的场景，如果并发写不多可以考虑 CopyOnWriteArrayList，但项目里我实际都是用普通集合配合单线程消费。</p><p><strong>面试答题话术</strong> 「我一般按三条线选：要不要顺序、要不要去重、要不要排序。List 默认 ArrayList，Set 默认 HashSet，Map 默认 HashMap；并发就 ConcurrentHashMap。LinkedHashMap 还能做 LRU——重写 removeEldestEntry，开 accessOrder，访问过的挪到尾部，超容量删最老的，我们本地缓存有过这个思路但最终用了 Redis。」</p><hr><h2 id="_7-fail-fast-与-fail-safe-★★☆" tabindex="-1">7. fail-fast 与 fail-safe ★★☆ <a class="header-anchor" href="#_7-fail-fast-与-fail-safe-★★☆" aria-label="Permalink to &quot;7. fail-fast 与 fail-safe ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> fail-fast 是「边遍历边盯着集合变没变」，一变就抛 ConcurrentModificationException（ArrayList、HashMap 的迭代器）。fail-safe 是「遍历的是快照」，改不影响遍历（CopyOnWriteArrayList、ConcurrentHashMap）。</p><p><strong>我的项目关联</strong> 遍历设备列表下发命令时，如果中途有增删就会踩 fail-fast。通用坑，我们没实际踩到，我写代码时会用 removeIf 或者先拷贝一份再遍历。</p><p><strong>面试答题话术</strong> 「fail-fast 靠 modCount 检测，遍历时集合结构变了立刻抛异常；fail-safe 遍历的是副本，不抛异常但读到的可能是旧数据。所以 for-each 里删元素要用 iterator.remove() 或者 removeIf，别直接 list.remove()。」</p><hr><h2 id="_8-泛型擦除-通配符-pecs-★★★" tabindex="-1">8. 泛型擦除 / 通配符 PECS ★★★ <a class="header-anchor" href="#_8-泛型擦除-通配符-pecs-★★★" aria-label="Permalink to &quot;8. 泛型擦除 / 通配符 PECS ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 泛型只在编译期存在，编译完类型参数就被擦掉了——<code>List&lt;String&gt;</code> 和 <code>List&lt;Integer&gt;</code> 运行时是同一个类，所以拿不到运行时的泛型实参。通配符口诀 PECS：<code>? extends T</code> 只能读不能写（生产数据），<code>? super T</code> 能写、读出来是 Object（消费数据）。</p><p><strong>我的项目关联</strong> 统一响应体 <code>Result&lt;T&gt;</code>、分页 <code>PageResult&lt;T&gt;</code>、Feign 接口的返回类型全靠泛型。网关里做协议报文到统一模型的转换时，用过 <code>Converter&lt;S, T&gt;</code> 这种泛型接口让每个厂商实现自己的转换。PECS 主要用在封装分页查询和通用转换工具上。</p><p><strong>面试答题话术</strong> 「泛型是编译期概念，编译完擦除，无界擦成 Object、有上界擦成上界，所以运行时拿不到实参，这也是泛型数组不能 new 的原因。通配符记 PECS：extends 用来读、super 用来写。项目里统一响应体、分页对象、Feign 返回值都用泛型，协议转换那层我用泛型接口让每个厂商实现自己的转换器，加厂商不用改上层。」</p><hr><h2 id="_9-反射-★★★" tabindex="-1">9. 反射 ★★★ <a class="header-anchor" href="#_9-反射-★★★" aria-label="Permalink to &quot;9. 反射 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 反射就是运行时拿到类的结构（构造器、字段、方法、注解）并调用它，绕开编译期的类型检查。框架全靠它：Spring 建 Bean、MyBatis 做结果映射。代价是慢（动态解析 + 安全检查）和破坏封装。</p><p><strong>我的项目关联</strong><strong>线上真实做法</strong>：协议插件化就是反射撑起来的——每个厂商的命令实现类上加自定义注解（云快充、新页、科陆各一套），应用启动时按包扫描把所有带注解的类扫出来，反射实例化后按「协议类型 + 命令字」注册进命令表。新增一条指令只要写个带注解的类，不用改主链路。反射对象我们启动时只做一次并缓存，不在请求链路上反射。</p><p><strong>面试答题话术</strong> 「反射是运行时获取类信息并调用。项目里我用来做协议插件化：启动时包扫描带注解的协议类，反射实例化后注册到命令表，这样加厂商加指令都不用改核心代码。反射慢是因为动态解析和安全检查，我们的做法是启动时一次性做完并缓存，运行期不反射，所以性能上没有负担。」</p><hr><h2 id="_10-注解与自定义注解-★★★-【简历亮点-高频追问】" tabindex="-1">10. 注解与自定义注解 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_10-注解与自定义注解-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;10. 注解与自定义注解 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 注解就是贴在代码上的标签，本身不改逻辑，得靠别人去读它——运行期用反射读，编译期用注解处理器读（Lombok 就是干这个的）。<code>@Retention</code> 决定它活到哪一步，只有 RUNTIME 才能在运行期反射拿到。</p><p><strong>我的项目关联</strong><strong>线上真实做法</strong>：自定义注解是我们项目里最常用的招式。协议命令类上的 <code>@YunKuaiChongCmd</code> 这种注解用来做插件注册；业务层的 <code>@RepeatSubmit</code> 防重复提交、基于注解的限流、AOP 切面统一鉴权，都是「注解 + 切面」的组合。写自定义注解时 <code>@Retention(RUNTIME)</code> + <code>@Target</code> 是固定搭配。</p><p><strong>面试答题话术</strong> 「注解本身只是元数据，生效要靠反射或者编译期处理器，只有 RUNTIME 的才能运行期拿到。项目里我大量用注解驱动实现：协议命令行加注解做自动注册，防重复提交、限流、统一鉴权都是自定义注解加 AOP 切面。好处是业务代码只加一行注解，横切逻辑集中在切面里，加功能不用改业务代码。」</p><hr><h2 id="_11-bigdecimal-与浮点精度-★★★-【简历亮点-高频追问】" tabindex="-1">11. BigDecimal 与浮点精度 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_11-bigdecimal-与浮点精度-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;11. BigDecimal 与浮点精度 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> float/double 是二进制浮点，像 0.1 这种十进制小数在二进制里是无限循环的，只能存近似值，所以 <code>0.1 + 0.2 != 0.3</code>。金额、电量、费率必须用 BigDecimal。三个坑：构造传字符串（<code>new BigDecimal(&quot;0.1&quot;)</code>）；divide 必须给精度或舍入模式，否则除不尽直接抛异常；比较用 compareTo 不用 equals（equals 连精度一起比，<code>1.0</code> 和 <code>1.00</code> 不相等）。</p><p><strong>我的项目关联</strong> 充电订单金额、分时电价折算、资金对账全程 BigDecimal。<strong>通用坑（我们没有实际踩到，但代码规范上一直在防）</strong>：一是 divide 不给 RoundingMode，某个地区电价除不尽会抛 ArithmeticException 把下单链路打断；二是对账用 equals 比金额，scale 不同会误判成对不上。我们的做法是统一封金额计算工具类，强制传精度和舍入模式，比较一律 compareTo。<strong>如果面试官追问「你们踩过吗」，就直说规范上防住了，没让它上线</strong>。</p><p><strong>面试答题话术</strong> 「金额场景我全程 BigDecimal。原因很直接，double 是二进制浮点，0.1 存的就是近似值，做对账迟早出问题。三个规范：构造一定传字符串，divide 一定带舍入模式，比较一定用 compareTo。项目里我们封了金额工具类把这些强制住——费率按秒折算的场景最容易除不尽，不指定舍入模式就会抛异常。」</p><hr><h2 id="_12-值传递-前端转全栈必考-★★★" tabindex="-1">12. 值传递（前端转全栈必考）★★★ <a class="header-anchor" href="#_12-值传递-前端转全栈必考-★★★" aria-label="Permalink to &quot;12. 值传递（前端转全栈必考）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Java 只有值传递。基本类型传的是值的副本，改不到外面；引用类型传的是「地址的副本」，副本和原引用指向同一个对象，所以改对象内容外面能看到，但把引用重新指向新对象外面看不到。</p><p><strong>我的项目关联</strong> 这条对我意义挺大——我从 JS 转过来，JS 对对象也是传引用副本，行为一致，所以上手没障碍。项目里协议报文的模型对象在多个 handler 之间传递、转换，靠的就是「改内容生效、换引用不生效」这个特性来理解数据流。</p><p><strong>面试答题话术</strong> 「Java 只有值传递。基本类型传值副本，引用类型传地址副本。所以方法里改对象字段外面能看到，但方法里重新 new 一个、或者把两个引用 swap，外面看不到。我从前端转过来，这块和 JS 对 Object 的行为是一致的，所以我理解上没有卡过。」</p><hr><h2 id="_13-异常体系-try-with-resources-★★★" tabindex="-1">13. 异常体系 / try-with-resources ★★★ <a class="header-anchor" href="#_13-异常体系-try-with-resources-★★★" aria-label="Permalink to &quot;13. 异常体系 / try-with-resources ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 根是 Throwable，分 Error（JVM 级故障，比如 OOM，不捕获）和 Exception。Exception 又分受检（编译期强制处理，如 IOException）和非受检（RuntimeException，比如 NPE，靠改代码而不是捕获）。finally 一定执行（除非 System.exit），try-with-resources 能自动关资源。</p><p><strong>我的项目关联</strong> 项目里自定义业务异常统一继承 RuntimeException，避免全链路污染 throws；对外接口在 Controller、Kafka 消费者、定时任务这些边界统一兜底捕获，记日志 + 转成友好响应。网关处理设备报文时，单个报文解析失败只丢这一条、不能让整个连接挂掉，所以每条处理的入口都包了异常兜底。</p><p><strong>面试答题话术</strong> 「受检异常是调用方能预判能恢复的，强制处理；非受检一般是编程错误，应该改代码。项目里我的自定义异常都继承 RuntimeException，不会有满屏 throws。捕获的位置我放在系统边界——Controller、消息消费者、定时任务，每个设备报文的处理入口也单独兜底，保证一条脏数据不会把整条连接搞崩，这个在我们网关里是明确的设计。」</p><hr><h2 id="_14-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" tabindex="-1">14. 什么时候抛、什么时候捕获 / throw vs throws ★★☆ <a class="header-anchor" href="#_14-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" aria-label="Permalink to &quot;14. 什么时候抛、什么时候捕获 / throw vs throws ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 自己能处理就捕获（重试、降级、记日志），处理不了或者调用方该知道的就往上抛。throw 是「抛出」一个异常对象，throws 是「声明」方法可能抛什么，一个动作一个声明。</p><p><strong>我的项目关联</strong> 互联互通对下游的调用失败会重试 + 降级返回，属于「能处理」；参数校验失败、设备不存在这种直接抛业务异常让上层统一转响应。原则是不吞异常、也不拿异常当流程控制。</p><p><strong>面试答题话术</strong> 「我的原则是能恢复就捕获，恢复不了或者调用方该知道就抛。throw 是抛对象，throws 是声明，别混。另外不在 catch 里无脑 <code>catch (Exception)</code> 然后返回 null，至少打日志，这是我在 review 里的硬要求。」</p><hr><h2 id="_15-final-finally-finalize-已废弃-★★☆" tabindex="-1">15. final / finally（finalize 已废弃）★★☆ <a class="header-anchor" href="#_15-final-finally-finalize-已废弃-★★☆" aria-label="Permalink to &quot;15. final / finally（finalize 已废弃）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> final 修类不能继承、修方法不能重写、修变量引用不能改。finally 是异常处理里一定会执行的那段。finalize 是对象回收前调用的方法，JDK9 起废弃了——执行时机不确定还能把对象「复活」，别用。</p><p><strong>我的项目关联</strong> 工具类、常量类用 final 修饰防止被继承破坏；协议命令的处理器基类被各厂商子类继承，但基类里的编解码入口方法是 final 的，保证流程不被改坏。finalize 项目里从没用过。</p><p><strong>面试答题话术</strong> 「final 和 finally 没有关系，只是拼写像。finalize 已经废弃了，因为执行时机不确定、可能延迟 GC、还能复活对象，要释放资源应该用 try-with-resources 或者 Cleaner。项目里我在命令处理器基类上把编解码主流程设成 final，只开放子类实现业务方法，保证流程一致。」</p><hr><h2 id="_16-类初始化顺序-★★☆" tabindex="-1">16. 类初始化顺序 ★★☆ <a class="header-anchor" href="#_16-类初始化顺序-★★☆" aria-label="Permalink to &quot;16. 类初始化顺序 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 顺序是：父类静态 → 子类静态 → 父类实例变量/代码块 → 父类构造器 → 子类实例变量/代码块 → 子类构造器。静态部分只在类第一次主动使用时执行一次。</p><p><strong>我的项目关联</strong> 协议处理器基类的静态块里注册通用配置，实例块做每个处理器自己的初始化，所以顺序必须是「静态先于实例」。这个是写代码时自然遵守的，没踩过坑。</p><p><strong>面试答题话术</strong> 「口诀是先静态后实例、先父后子，静态只执行一次。new 子类会先初始化父类。这个我一般在写继承体系的时候会注意，比如基类的静态注册一定要先于子类实例的构建。」</p><hr><h2 id="_17-不可变类-★★★" tabindex="-1">17. 不可变类 ★★★ <a class="header-anchor" href="#_17-不可变类-★★★" aria-label="Permalink to &quot;17. 不可变类 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 四步：类 final、字段 private final、不给 setter、可变字段（数组/集合/Date）在构造和 getter 上做防御性拷贝。String、Integer、BigDecimal、LocalDate 都是这么做的。</p><p><strong>我的项目关联</strong> 协议里解析出来的报文对象、费率配置对象，我们尽量做成不可变的，避免在多个 handler 之间被意外改掉。费率、金额这种配置类尤其，一旦可变很容易出现「某个地方算错了费率」这种难查的问题。</p><p><strong>面试答题话术</strong> 「不可变类就是 final 类 + private final 字段 + 不提供 setter，如果字段是集合或日期还要防御性拷贝。好处是线程安全、可以被安全共享。项目里费率、金额这种配置对象我倾向做成不可变的，避免在多个处理环节被误改。String 就是标准实现，它不可变所以能进常量池、能当 key。」</p><hr><h2 id="_18-字节码-jdk-jre-jvm-★★★" tabindex="-1">18. 字节码 / JDK-JRE-JVM ★★★ <a class="header-anchor" href="#_18-字节码-jdk-jre-jvm-★★★" aria-label="Permalink to &quot;18. 字节码 / JDK-JRE-JVM ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 源码用 javac 编译成字节码（.class），JVM 负责执行；字节码跟平台无关，所以「一次编译到处运行」。JDK ⊃ JRE ⊃ JVM——JVM 负责跑，JRE 是 JVM + 核心类库，JDK 再多了编译器这些开发工具。</p><p><strong>我的项目关联</strong> 网关用 JDK21 跑，基础镜像是 jre，构建阶段才用 jdk，靠多阶段构建把镜像做小。字节码层面我们没直接操作过，但 AOP 代理、协议插件的动态注册都发生在这一层之下。</p><p><strong>面试答题话术</strong> 「字节码是 JVM 的中间指令，跟平台无关，各平台 JVM 负责翻译执行，所以能跨平台；JIT 还能把热点字节码编译成本地机器码提速。JDK 包含 JRE 包含 JVM。项目里 Docker 构建阶段用 jdk，运行镜像用 jre，就是为了减小体积。」</p><hr><h2 id="_19-hash-冲突的解决办法-★★★" tabindex="-1">19. hash 冲突的解决办法 ★★★ <a class="header-anchor" href="#_19-hash-冲突的解决办法-★★★" aria-label="Permalink to &quot;19. hash 冲突的解决办法 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 常见四种：链地址法（冲突的挂成链表，HashMap 用这个）、开放定址法（往后探测空位，ThreadLocalMap 用线性探测）、再哈希、公共溢出区。HashMap 选链地址是因为实现简单、删除方便，链长了还能转红黑树。</p><p><strong>我的项目关联</strong> 知道结论就够了——我们不需要自己实现哈希表。实际相关的是设备分片：Kafka 按设备号哈希分区时，用的是 murmur3_128 而不是简单取模，就是为了让分片更均匀，避免某几个分区成热点。</p><p><strong>面试答题话术</strong> 「主要是链地址法和开放定址法，HashMap 用链地址，链表长了转红黑树把最坏情况从 O(n) 降到 O(logn)；ThreadLocalMap 用的是线性探测。项目里我真正用到哈希思想的地方是数据分片——Kafka 按设备号哈希，用 murmur3 保证分布均匀，防止热点分区。」</p><hr><h2 id="_20-bio-nio-aio-★★★-【简历亮点-高频追问】" tabindex="-1">20. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_20-bio-nio-aio-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;20. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> BIO 是一连接一线程，读写都阻塞，扛不住高并发。NIO 是同步非阻塞 + 多路复用，一个线程用 Selector 管一堆连接，谁有事件处理谁。AIO 是异步，读写完成回调通知你。NIO 三大件：Buffer（缓冲区）、Channel（双向通道）、Selector（多路复用器），底层靠 Linux 的 epoll。</p><p><strong>我的项目关联</strong><strong>线上</strong>：我们的充电桩协议网关就是基于 Netty（NIO 封装）做的 TCP 长连接服务，向上对接业务、向下接各厂商充电桩。为什么不用 BIO：设备量上去以后一连接一线程扛不住；为什么不用 AIO：Linux 上实现不成熟，还是 epoll 模拟，跨平台一致性不如 NIO。Netty 的 ChannelHandler 链路正好把编解码、心跳、鉴权拆成独立 handler。</p><p><strong>面试答题话术</strong> 「BIO 一连接一线程，扛不住高并发；NIO 是多路复用，一个 Selector 管很多连接，底层是 epoll；AIO 是异步回调，但 Linux 上不成熟。我们的协议网关选 Netty，本质是 NIO，理由是设备长连接场景需要多路复用，而且 Netty 的 handler 链路能把编解码、心跳、鉴权拆开，职责清晰。AIO 我没用过，主要是不成熟。」</p><hr><h2 id="_21-虚拟线程-vs-平台线程-★★★-【简历亮点-高频追问】" tabindex="-1">21. 虚拟线程 vs 平台线程 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_21-虚拟线程-vs-平台线程-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;21. 虚拟线程 vs 平台线程 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 平台线程 1:1 绑操作系统线程，贵，几千个就到头；虚拟线程是 JVM 调度的 M:N，挂在少量载体线程上，IO 阻塞时会自动卸载，载体线程立刻去跑别的任务。所以只适合 IO 密集型，CPU 密集型用没收益还多一层调度。</p><p><strong>我的项目关联</strong><strong>线上</strong>：我们的网关和互联互通服务是典型 IO 密集型——等数据库、等下游 HTTP、等 Redis，Java 21 升级后把这类业务换成 <code>Executors.newVirtualThreadPerTaskExecutor()</code>。踩到两个点：一是数据库连接池上限没变，线程多了但池子还是那么大，所以关键是别让连接被长时间占着；二是老代码里有 <code>synchronized</code> 包着 IO 的会 pin 住载体线程，这类改成了 ReentrantLock。</p><p><strong>面试答题话术</strong> 「虚拟线程我在网关和互联互通服务里实际用过，这两个服务都是 IO 密集型的，收益比较明显。原理上平台线程 1:1 映射 OS 线程，虚拟线程是 JVM 调度的 M:N，阻塞时自动卸载让载体线程去干别的。落地踩了两个点：连接池并发上限不会跟着变，真正要控的是连接占用时长；还有 synchronized 包 IO 会 pin 住载体线程，我们换成 ReentrantLock 就好了。CPU 密集的任务我没用，没收益。」</p><hr><h2 id="_22-函数式接口-lambda-stream-★★★" tabindex="-1">22. 函数式接口 / Lambda / Stream ★★★ <a class="header-anchor" href="#_22-函数式接口-lambda-stream-★★★" aria-label="Permalink to &quot;22. 函数式接口 / Lambda / Stream ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 函数式接口就是只有一个抽象方法的接口。Lambda 是它的简写实现。Stream 是「数据源 → 中间操作（惰性，不立刻执行）→ 终结操作（触发执行）」的流水线，中间操作要等终结操作才跑。</p><p><strong>我的项目关联</strong> 项目里用得最多的是 Stream：List 转 Map（设备列表转 <code>Map&lt;设备号, 设备&gt;</code>）、按条件过滤订单、分组统计（按场站/按日期分组算金额）、集合转换。<code>parallelStream</code> 我用得很克制——它用的是共享的 ForkJoinPool，如果里面还做阻塞 IO 会拖垮整个池子，我们这种 IO 场景基本不用并行流。</p><p><strong>面试答题话术</strong> 「Stream 是惰性的，没有终结操作中间操作不执行；map 是一对一，flatMap 是一对多拍平。项目里我主要用 Stream 做集合转换和分组统计，比如设备列表转 Map、订单按场站分组。parallelStream 我基本不用——它共享 ForkJoinPool，里面一旦有阻塞操作会把整个池子拖垮，我们的场景都是 IO 密集型，不适合。」</p><hr><h2 id="_23-optional-java-8-新特性-★★★" tabindex="-1">23. Optional / Java 8 新特性 ★★★ <a class="header-anchor" href="#_23-optional-java-8-新特性-★★★" aria-label="Permalink to &quot;23. Optional / Java 8 新特性 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Optional 是包装「可能为空的值」的容器，让「可能没值」这件事在方法签名上就看得见。<code>orElse</code> 无论有没有值都会算参数，<code>orElseGet</code> 才是惰性的。用法上它只适合当方法返回值，不当字段、不当参数。</p><p><strong>我的项目关联</strong> 项目里查询接口返回单个对象时用 Optional 表达「可能查不到」，比如按设备号查在线设备。但更多场景我直接用返回 null + 业务判断，因为 Optional 用在字段和参数上反而增加复杂度。Java 8 的 Stream、新时间 API、CompletableFuture 是项目里天天在用的。</p><p><strong>面试答题话术</strong> 「Optional 主要是把「可能为空」显式化，用法上只建议当返回值。坑是 orElse 不管有没有值都会执行参数，所以有开销的兜底要用 orElseGet。项目里查单个对象我用它，但字段和参数不用，那样反而更啰嗦。」</p><hr><h2 id="_24-jdk-版本演进-8-11-17-21-★★☆" tabindex="-1">24. JDK 版本演进 8/11/17/21 ★★☆ <a class="header-anchor" href="#_24-jdk-版本演进-8-11-17-21-★★☆" aria-label="Permalink to &quot;24. JDK 版本演进 8/11/17/21 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 8 是分水岭（Lambda、Stream、Optional、新时间 API）；11 加了 var、新 HTTP Client；17 加了 record、sealed、文本块、instanceof 模式匹配；21 的杀手锏是虚拟线程。</p><p><strong>我的项目关联</strong> 我们新服务直接上 Java 21 + Spring Boot 3.x，所以 17 的记录类、文本块、switch 表达式都在用，21 的虚拟线程用在 IO 密集服务。等于跳过了 8 到 17 的历史包袱，这点我面试时会当成优势讲——不用背兼容性负担。</p><p><strong>面试答题话术</strong> 「我们新服务是 Java 21 + Spring Boot 3.4，所以直接吃到了 record、文本块、模式匹配这些红利，虚拟线程也实打实用在 IO 密集服务上。8 的 Lambda、Stream、Optional 是基础，新时间 API 我要求自己全用 LocalDateTime，不用老的 Date。」</p><hr><h2 id="_25-comparable-与-comparator-★★☆" tabindex="-1">25. Comparable 与 Comparator ★★☆ <a class="header-anchor" href="#_25-comparable-与-comparator-★★☆" aria-label="Permalink to &quot;25. Comparable 与 Comparator ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> Comparable 是「我自己知道自己怎么排序」——类实现 compareTo，只有一种自然顺序。Comparator 是「外人给我定排序规则」——不改原类，能定义多种，配合 lambda 很方便。</p><p><strong>我的项目关联</strong> 订单列表按时间倒序、设备按上线时间排序，我用 <code>Comparator.comparing(...).thenComparing(...)</code> 在调用处拼，不往实体类里塞排序逻辑。需要多字段排序（先按场站再按时间）的时候 Comparator 明显更方便。</p><p><strong>面试答题话术</strong> 「Comparable 是类自己实现的自然排序，只能一种；Comparator 是外部规则，能多种，也不侵入原类。我一般用 Comparator，链式写多字段排序很清爽，比如先按场站再按时间。」</p><hr><h2 id="_26-枚举-★★☆" tabindex="-1">26. 枚举 ★★☆ <a class="header-anchor" href="#_26-枚举-★★☆" aria-label="Permalink to &quot;26. 枚举 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 枚举本质是继承 Enum 的 final 类，每个常量都是唯一实例，构造器私有。它天然防反射、防反序列化破坏，所以是实现单例最稳的方式。</p><p><strong>我的项目关联</strong> 项目里大量用枚举表达固定集合：订单状态、设备状态、协议类型、支付渠道、故障码。特别是订单状态机，状态流转判断全靠枚举。枚举里挂字段（比如状态码 + 中文描述）是我们的常规写法。</p><p><strong>面试答题话术</strong> 「枚举是 final 类，实例唯一，天然防反射和反序列化，所以是单例的最佳实践。项目里订单状态、设备状态、协议类型、支付渠道都是枚举，枚举里带 code 和描述字段是我们的标准写法。状态机判断流转合法性也基于枚举。」</p><hr><h2 id="_27-object-常用方法-★★☆" tabindex="-1">27. Object 常用方法 ★★☆ <a class="header-anchor" href="#_27-object-常用方法-★★☆" aria-label="Permalink to &quot;27. Object 常用方法 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> equals、hashCode、toString、clone、getClass，加上线程协作的 wait/notify/notifyAll。finalize 已经废弃，忽略。</p><p><strong>我的项目关联</strong> DTO 和实体类都会重写 toString 方便打日志——网关排查设备报文问题时主要靠日志，toString 写清楚省事。wait/notify 项目里基本不用，线程协作我们走并发包的工具类。</p><p><strong>面试答题话术</strong> 「常用的是 equals、hashCode、toString、clone、getClass，还有 wait/notify 这三个。finalize 废弃了不用提。项目里我特别重视 toString，因为设备报文排查基本靠日志，对象打出来能看懂很关键。」</p><hr><h2 id="_28-深拷贝浅拷贝-serialversionuid-★★☆" tabindex="-1">28. 深拷贝浅拷贝 / serialVersionUID ★★☆ <a class="header-anchor" href="#_28-深拷贝浅拷贝-serialversionuid-★★☆" aria-label="Permalink to &quot;28. 深拷贝浅拷贝 / serialVersionUID ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 浅拷贝只复制对象本身，里面的引用字段还指向同一个对象；深拷贝是把引用链上的对象全复制一份。<code>clone()</code> 默认是浅拷贝。serialVersionUID 是序列化版本号，不显式声明的话类一改旧数据就反序列化失败。</p><p><strong>我的项目关联</strong> 跨服务传对象走序列化（网关 → 业务服务、网关 → 下游运营商），DTO 我们统一显式声明 serialVersionUID，避免加个字段就反序列化不兼容。深拷贝项目里用得少，有个配置快照场景直接用的序列化拷贝，没自己写 clone。</p><p><strong>面试答题话术</strong> 「浅拷贝是引用共享，深拷贝是引用链全复制。项目里我更多是保证 DTO 显式声明 serialVersionUID，防止类改动导致反序列化不兼容。深拷贝我们用序列化方式做过配置快照。知道结论、能用对就行，不用背 clone 的实现细节。」</p><hr><h2 id="_29-四种内部类-★☆☆" tabindex="-1">29. 四种内部类 ★☆☆ <a class="header-anchor" href="#_29-四种内部类-★☆☆" aria-label="Permalink to &quot;29. 四种内部类 ★☆☆&quot;">​</a></h2><p>一句话：成员 / 静态 / 局部 / 匿名四种。业务里只用静态内部类（Builder、静态工具）和匿名内部类（现在基本被 Lambda 替代）。唯一要记的结论——<strong>静态内部类不持有外部引用，不会内存泄漏</strong>。不用复习。</p><hr><h2 id="_30-重载与重写-★☆☆" tabindex="-1">30. 重载与重写 ★☆☆ <a class="header-anchor" href="#_30-重载与重写-★☆☆" aria-label="Permalink to &quot;30. 重载与重写 ★☆☆&quot;">​</a></h2><p>一句话：重载看参数列表、编译期决定、同一个类里；重写看方法签名一致、运行期决定、父子类之间。只返回值不同不算重载，静态方法不能被重写只会被隐藏。低频，扫一眼即可。</p>',148)]))}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
